mapper.update:
UPDATE environment_work
SET metadata = CAST(#{params.Metadata,sensitive=true} AS jsonb),
    updated_at = NOW()
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND environment_external_id = #{params.EnvironmentExternalID}
AND external_id = #{params.WorkExternalID}
AND deleted_at IS NULL
RETURNING

UPDATE environment_work
SET metadata = COALESCE(metadata, CAST('{}' AS jsonb))
        || CAST(#{params.MetadataPatch,sensitive=true} AS jsonb),
    updated_at = NOW()
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND environment_uuid = #{params.EnvironmentUUID}
AND environment_external_id = #{params.EnvironmentExternalID}
AND external_id = #{params.WorkExternalID}
AND deleted_at IS NULL

UPDATE environment_work
SET state = #{params.State},
    latest_heartbeat_at = NOW(),
    heartbeat_ttl_seconds = #{params.TTLSeconds},
    updated_at = NOW()
WHERE uuid = #{params.WorkUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND environment_external_id = #{params.EnvironmentExternalID}
RETURNING

UPDATE environment_work
SET state = CASE WHEN state = 'stopped' THEN state ELSE 'stopping' END,
    stop_requested_at = COALESCE(stop_requested_at, NOW()),
    updated_at = NOW()
WHERE workspace_uuid = #{workspaceUUID}
AND environment_external_id = #{environmentExternalID}
AND data->>'id' = #{sessionExternalID}
AND deleted_at IS NULL
AND state <> 'stopped'

mapper.select:
SELECT
    CAST(COUNT(*) FILTER (
        WHERE state = 'queued'
        AND (claim_expires_at IS NULL OR claim_expires_at <= NOW())
    ) AS int) AS depth,
    CAST(COUNT(*) FILTER (WHERE state <> 'stopped') AS int) AS pending,
    MIN(created_at) FILTER (WHERE state = 'queued') AS oldest_queued_at,
    COALESCE((
        SELECT CAST(COUNT(DISTINCT worker_id) AS int)
        FROM environment_worker_polls p
        WHERE p.workspace_uuid = #{workspaceUUID}
        AND p.environment_external_id = #{environmentExternalID}
        AND p.last_poll_at > NOW() - INTERVAL '30 seconds'
    ), 0) AS workers_polling
FROM environment_work
WHERE workspace_uuid = #{workspaceUUID}
AND environment_external_id = #{environmentExternalID}
AND deleted_at IS NULL
